package native

const hostNotificationContractsJSON = `{"galaxy_host_notifications_status":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"Read local host reminder state. Starts no OS helper, timer or model. Restart requires a new explicit enable choice.","write":false,"choice":false},"galaxy_host_notifications_permission":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"After a separate explicit choice, ask the configured macOS helper for OS alert permission if it has never been decided. Does not enable reminders, show a notification, poll the inbox, or change Galaxy read state. Denied permission stays denied.","write":true,"choice":true},"galaxy_host_notifications_enable":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"Enable generic system reminders in this running native process after an explicit choice. Check the current inbox every 60 seconds; send no private source text to the OS and never mark human read.","write":true,"choice":true},"galaxy_host_notifications_disable":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"Stop host reminder checks and withdraw owned prompts. Remote business events and human read remain unchanged.","write":true,"choice":false},"galaxy_host_notifications_check":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"Check reminders only while already enabled. Unavailable or unconfirmed system delivery leaves the foreground inbox available; no model call.","write":true,"choice":false},"galaxy_host_notifications_reconcile":{"schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{},"additionalProperties":false},"description":"Acknowledge only original locally observed display receipts, including after disabling. Never show again or mark a human as having read.","write":true,"choice":false}}`
